try:
    mask = (df['row_kind'].isin(['counted', 'netted'])) & (df['currency'] == 'USD')
    df_seg = df[mask].copy()

    seg_mrr = df_seg.groupby('segment')['mrr'].sum().reset_index()
    total_mrr = seg_mrr['mrr'].sum()

    seg_results = [{"name": str(row['segment']), "value": round(float(row['mrr']), 2)}
                   for _, row in seg_mrr.iterrows()]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "sum",
        "label": "mrr_by_segment",
        "results": seg_results
    })

    seg_count = df_seg.groupby('segment')['customer_id'].nunique().reset_index()
    count_results = [{"name": str(row['segment']), "value": float(row['customer_id'])}
                     for _, row in seg_count.iterrows()]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "customer_id",
        "aggregation": "count",
        "label": "paying_customers_by_segment",
        "results": count_results
    })

    seg_arpa = df_seg.groupby('segment').apply(
        lambda g: g['mrr'].sum() / g['customer_id'].nunique() if g['customer_id'].nunique() > 0 else 0
    ).reset_index()
    seg_arpa.columns = ['segment', 'arpa']
    arpa_results = [{"name": str(row['segment']), "value": round(float(row['arpa']), 2)}
                    for _, row in seg_arpa.iterrows()]

    result['segments'].append({
        "segment_column": "segment",
        "metric_column": "mrr",
        "aggregation": "mean",
        "label": "arpa_by_segment",
        "results": arpa_results
    })

    result['assumptions'].append("MRR by segment uses only USD rows with row_kind in ['counted','netted']; summed per segment.")
    result['assumptions'].append("Customer count per segment uses distinct customer_id values.")
    result['assumptions'].append("ARPA = total segment MRR / distinct customers in segment.")

except Exception as e:
    result['assumptions'].append(f"Segmentation error: {str(e)}")

